;------------------------------------------------------------------------------
; Offsets into the combat area at StartUp (24C4: the tail of a CNFLCT file, FORMATS.md 5),
; used as `CmbMonHP[si]` with SI = StartUp + n (the ORG places them at the offset's value):
;   Ofs80h (80h), CmbMonY (88h): the 8 monsters' x and y
;   CmbMonUnder (90h): the tile under each monster (put back when it dies, COMBAT 8F80)
;   CmbMonHP (98h): monsters' hit points, 0 = dead (COMBAT 8F66 subtracts the damage)
;   CmbPlrX (0A0h), CmbPlrY (0A4h): the 4 players' x and y (0FFh = not fighting)
;   CmbPlrUnder (0A8h): the tile under each player (COMBAT 8A19, 8C78)
;   CmbPlrTile (0ACh): each player's own tile, from his class (COMBAT 8A0F, CombatClassTiles)
; LOOP 1F96 also uses Ofs80h as a plain 80h: `Ofs80h[bx]` with BX in MonTile = MonTalk.
;------------------------------------------------------------------------------
ORG 80h
Ofs80h label byte
ORG 88h
CmbMonY label byte
ORG 90h
CmbMonUnder label byte
ORG 98h
CmbMonHP label byte
ORG 0A0h
CmbPlrX label byte
ORG 0A4h
CmbPlrY label byte
ORG 0A8h
CmbPlrUnder label byte
ORG 0ACh
CmbPlrTile label byte
ORG 100h
;------------------------------------------------------------------------------
; MapBuf: the map file is loaded here (LoadFile, 1228h bytes): 64 x 64 map bytes (shape * 4),
; at 1100 the town speeches, 1280-131F the 32 creature slots, 1320-1327 state (FORMATS.md 3).
; In a dungeon: DUNGEON.DAT at 0100-084A, the dungeon file at 0900-1189 (FORMATS.md 4, 8).
;------------------------------------------------------------------------------
MapBuf label byte
	db 2048 dup (0)	;@0100
; DungeonMap: a dungeon's eight 16 x 16 levels (0900-10FF), when in a dungeon.
DungeonMap label byte
	db 1381 dup (0)	;@0900
; DawnCell = MapBuf + 53 * 64 + 37: the overworld cell of Dawn. WORLD (211E) writes
; 18h (Towne) when both moons are in phase 7 and 0Ch (Forest) when both are 0: Dawn comes and
; goes with the moons.
DawnCell label byte
	db 667 dup (0)	;@0E65
; MapText: town speeches (offset table + strings), or the dungeon's level messages.
MapText label byte
	db 384 dup (0)	;@1100
; The 32 creature slots (FORMATS.md 3): tile (shape * 4, 0 = empty), movement code, x, y,
; talk code.
MonTile label byte
	db 32 dup (0)	;@1280
MonUnder label byte
	db 32 dup (0)	;@12A0
MonX label byte
	db 32 dup (0)	;@12C0
MonY label byte
	db 32 dup (0)	;@12E0
MonTalk label byte
	db 32 dup (0)	;@1300
; Map state (saved with the map file; Sosaria only). 1320-1323 are the WHIRLPOOL, not the moon
; gate as FORMATS.md 3 says: PARTY 7347-7403 moves it every 4th turn by (dx, dy) when the cell
; is water, destroys a frigate it meets (2Ch -> whirlpool 30h), and WORLD 21A4 puts it back at
; (3, 7-3Dh) after it has swallowed the party. SOSARIA.ULT starts it at (5, 3Ah).
WhirlpoolX label byte
	db 0h	; x	;@1320
WhirlpoolY label byte
	db 0h	; y	;@1321
WhirlpoolDX label byte
	db 0h	; WhirlpoolDX: step in x (PARTY table L7337)	;@1322
WhirlpoolDY label byte
	db 0h	; WhirlpoolDY: step in y (L733F)	;@1323
Moon1Phase label byte
	db 0h	; 0-7	;@1324
Moon2Phase label byte
	db 0h	;@1325
Moon1Count label byte
	db 0h	; steps to Moon1's next phase (12)	;@1326
Moon2Count label byte
	db 0h	; steps to Moon2's next phase (4)	;@1327
	dw StartUp	; the entry vector, right after the map buffer: BOOTUP jumps through 1328	;@1328
; ScreenRowTbl: the screen offset of each of the 200 scan lines (0000, 2000, 0050, 2050, ...);
; DUNGEON.DAT reads it as ROWTAB.
ScreenRowTbl label byte
	db 0h,0h,0h,20h,50h,0h,50h,20h,0A0h,0h,0A0h,20h,0F0h,0h,0F0h,20h	;@132A
	db 40h,1h,40h,21h,90h,1h,90h,21h,0E0h,1h,0E0h,21h,30h,2h,30h,22h	;@133A
	db 80h,2h,80h,22h,0D0h,2h,0D0h,22h,20h,3h,20h,23h,70h,3h,70h,23h	;@134A
	db 0C0h,3h,0C0h,23h,10h,4h,10h,24h,60h,4h,60h,24h,0B0h,4h,0B0h,24h	;@135A
	db 0h,5h,0h,25h,50h,5h,50h,25h,0A0h,5h,0A0h,25h,0F0h,5h,0F0h,25h	;@136A
	db 40h,6h,40h,26h,90h,6h,90h,26h,0E0h,6h,0E0h,26h,30h,7h,30h,27h	;@137A
	db 80h,7h,80h,27h,0D0h,7h,0D0h,27h,20h,8h,20h,28h,70h,8h,70h,28h	;@138A
	db 0C0h,8h,0C0h,28h,10h,9h,10h,29h,60h,9h,60h,29h,0B0h,9h,0B0h,29h	;@139A
	db 0h,0Ah,0h,2Ah,50h,0Ah,50h,2Ah,0A0h,0Ah,0A0h,2Ah,0F0h,0Ah,0F0h,2Ah	;@13AA
	db 40h,0Bh,40h,2Bh,90h,0Bh,90h,2Bh,0E0h,0Bh,0E0h,2Bh,30h,0Ch,30h,2Ch	;@13BA
	db 80h,0Ch,80h,2Ch,0D0h,0Ch,0D0h,2Ch,20h,0Dh,20h,2Dh,70h,0Dh,70h,2Dh	;@13CA
	db 0C0h,0Dh,0C0h,2Dh,10h,0Eh,10h,2Eh,60h,0Eh,60h,2Eh,0B0h,0Eh,0B0h,2Eh	;@13DA
	db 0h,0Fh,0h,2Fh,50h,0Fh,50h,2Fh,0A0h,0Fh,0A0h,2Fh,0F0h,0Fh,0F0h,2Fh	;@13EA
	db 40h,10h,40h,30h,90h,10h,90h,30h,0E0h,10h,0E0h,30h,30h,11h,30h,31h	;@13FA
	db 80h,11h,80h,31h,0D0h,11h,0D0h,31h,20h,12h,20h,32h,70h,12h,70h,32h	;@140A
	db 0C0h,12h,0C0h,32h,10h,13h,10h,33h,60h,13h,60h,33h,0B0h,13h,0B0h,33h	;@141A
	db 0h,14h,0h,34h,50h,14h,50h,34h,0A0h,14h,0A0h,34h,0F0h,14h,0F0h,34h	;@142A
	db 40h,15h,40h,35h,90h,15h,90h,35h,0E0h,15h,0E0h,35h,30h,16h,30h,36h	;@143A
	db 80h,16h,80h,36h,0D0h,16h,0D0h,36h,20h,17h,20h,37h,70h,17h,70h,37h	;@144A
	db 0C0h,17h,0C0h,37h,10h,18h,10h,38h,60h,18h,60h,38h,0B0h,18h,0B0h,38h	;@145A
	db 0h,19h,0h,39h,50h,19h,50h,39h,0A0h,19h,0A0h,39h,0F0h,19h,0F0h,39h	;@146A
	db 40h,1Ah,40h,3Ah,90h,1Ah,90h,3Ah,0E0h,1Ah,0E0h,3Ah,30h,1Bh,30h,3Bh	;@147A
	db 80h,1Bh,80h,3Bh,0D0h,1Bh,0D0h,3Bh,20h,1Ch,20h,3Ch,70h,1Ch,70h,3Ch	;@148A
	db 0C0h,1Ch,0C0h,3Ch,10h,1Dh,10h,3Dh,60h,1Dh,60h,3Dh,0B0h,1Dh,0B0h,3Dh	;@149A
	db 0h,1Eh,0h,3Eh,50h,1Eh,50h,3Eh,0A0h,1Eh,0A0h,3Eh,0F0h,1Eh,0F0h,3Eh	;@14AA
;------------------------------------------------------------------------------
; PARTY.ULT is loaded here (112h bytes): the 18-byte header (FORMATS.md 6) ...
;------------------------------------------------------------------------------
PartyTile label byte
	db 0h,0h	; the party's tile (3Fh on foot, 0Ah horse, 0Bh frigate); 14BB not read	;@14BA
Location label byte	;@14BC
	db 0h	; 0 Sosaria, 1 dungeon, 0FFh Ambrosia, 80h combat, 2-4 ?	;@14BC
MoveCount label byte
	db 0h	; MoveCount: 8 BCD digits, low byte first	;@14BD
MoveCountB1 label byte
	db 0h	; MoveCount, byte 1	;@14BE
MoveCountB2 label byte
	db 0h	; MoveCountB2	;@14BF
MoveCountB3 label byte
	db 0h	; MoveCountB3	;@14C0
PartySize label byte
	db 0h	; 1-4	;@14C1
PartyXY label byte
	db 0h,0h,0h,0h,0h,0h	; x, y saved (outside a town: the town's position); 14C4-14C7 not read	;@14C2
ExoticWeaponFound label byte
	db 0h	; 0FFh = not found yet (weapon menu of Ready?)	;@14C8
ExoticArmourFound label byte
	db 0h	; (armour menu?)	;@14C9
ExtraWeaponsOk label byte
	db 0h	; set by ShopListWeapons in Dawn: +2 and +4 weapons for sale	;@14CA
ExtraArmoursOk label byte
	db 0h	; set by ShopListArmour in Dawn: +2 armours for sale	;@14CB
; ... and the four character records (64 bytes each, FORMATS.md 6). The initial contents
; (14 spaces, 0FFh at offset 0Eh) are overwritten by the load.
Players label byte
	db 20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,0FFh,0h	;@14CC
	db 0h	;@14DC
PlrStatus label byte
	db 0h,0h,0h	; Players+11h (status) of slot 0, indexed by slot * 40h	;@14DD
PlrInt label byte
	db 44 dup (0)	; Players+14h (intelligence), indexed by slot * 40h	;@14E0
	db 20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,0FFh,0h	;@150C
	db 48 dup (0)	;@151C
	db 20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,0FFh,0h	;@154C
	db 48 dup (0)	;@155C
; Player4: the fourth record.
Player4 label byte
	db 20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,20h,0FFh,0h	;@158C
	db 48 dup (0)	;@159C
; The game's variables (not in PARTY.ULT).
PlayerXY label byte
	db 0h	; the party's current x	;@15CC
PlayerY label byte
	db 0h	; current y	;@15CD
LightOn label byte
	db 0h	; a torch burns: the dungeon view is drawn (DUNGEON.DAT)	;@15CE
DungeonLevel label byte
	db 0h	; 0-7	;@15CF
TimeStop label byte
	db 0h	; Negate Time: turns left with the creatures stopped (10)	;@15D0
RideToggle label byte
	db 1h	; RideToggle: on horse or ship, creatures move every other step	;@15D1
LastKey label byte
	db 0h,0h	; LastKey: the command's key word (scan code, char), from ReadCommand	;@15D2
