;------------------------------------------------------------------------------
; ReadCommand: the top of a surface turn: draw the view (BuildView), check the
; party (PARTY CheckAllOut: is anyone still up?), print the prompt character 10h and wait for a key,
; at most about 5 seconds (DOS time; the whirlpool moves meanwhile, PARTY MoveWhirlpool); no key =
; Space (Pass). Letters are made upper case, the key word is looked up in SurfaceKeys ("What?"
; if absent) and stored in LastKey, SI = its prompt, and its handler is jumped to.
; ReadCommandNoView skips the view. Reached by jumps (WORLD 257F, 22A2); the handlers
; end in MainLoop (LOOP), which comes back here through WORLD (22A2).
;------------------------------------------------------------------------------
ReadCommand:	call BuildView	;@1B77
ReadCommandNoView:	call CheckAllOut	;@1B7A
	mov al, 10h	; prompt character 10h	;@1B7D
	call PutChar	;@1B7F
	mov ah, 2Ch	; DOS: get time: DH = seconds	;@1B82
	int 21h	;@1B84
	mov bl, dh	;@1B86
	add bl, 5	; wait until 5 seconds later	;@1B88
	cmp bl, 3Ch	;@1B8B
	jb ReadCommand_Wait	;@1B8E
	sub bl, 3Ch	;@1B90
ReadCommand_Wait:	call MoveWhirlpool	; whirlpool: moves every 4th pass (CPU speed ?)	;@1B93
	call KeyReady	;@1B96
	jne ReadCommand_Key	;@1B99
	mov ah, 2Ch	; DOS: get time	;@1B9B
	int 21h	;@1B9D
	cmp bl, dh	;@1B9F
	jne ReadCommand_Wait	;@1BA1
	mov ax, 3920h	; no key: Space (Pass)	;@1BA3
	jmp short ReadCommand_Find	;@1BA6
ReadCommand_Key:	call ReadKey	;@1BA8
	cmp al, 61h	; lower case to upper	;@1BAB
	jb ReadCommand_Find	;@1BAD
	cmp al, 7Ah	;@1BAF
	ja ReadCommand_Find	;@1BB1
	sub al, 20h	;@1BB3
ReadCommand_Find:	mov cx, 21h	; 33 commands	;@1BB5
	mov bx, cx	;@1BB8
	lea di, SurfaceKeys	;@1BBA
	repne scasw	;@1BBE
	je ReadCommand_Found	;@1BC0
	jmp MsgWhat	;@1BC2
ReadCommand_Found:	sub bx, cx	; BX = index * 2	;@1BC5
	dec bx	;@1BC7
	shl bx, 1	;@1BC8
	mov si, word ptr SurfacePrompts[bx]	; SI = the prompt	;@1BCA
	mov word ptr LastKey, ax	; LastKey	;@1BCE
	jmp word ptr SurfaceCmds[bx]	;@1BD1
CODE ENDS
END
